import { useEffect, useMemo, useState, useRef } from "react";
import {
  Form,
  Button,
  Row,
  Col,
  Container,
  Alert,
  Table,
  Nav,
  Navbar,
} from "react-bootstrap";
import { getSubjects } from "../api/api";
import { useNavigate } from "react-router-dom";

function SyllabusManager() {
  const inputRef = useRef(null);

  const navigate = useNavigate();
  const [subjects, setSubjects] = useState([]);
  const [error, setError] = useState("");

  const [search, setSearch] = useState("");
  const [codeFilter, setCodeFilter] = useState("");

  const loadSubjects = () => {
    getSubjects()
      .then((data) => setSubjects(data))
      .catch(() => setError("Không thể tải danh sách khóa học."));
  };

  useEffect(() => {
    loadSubjects();
  }, []);

  const code = useMemo(
    () => [...new Set(subjects.map((s) => s.code))],
    [subjects],
  );

  const filteredSubjects = useMemo(() => {
    const keyword = search.trim().toLowerCase();
    return subjects.filter((s) => {
      const matchesKeyword =
        !keyword ||
        s.code?.toLowerCase().includes(keyword) ||
        s.name?.toLowerCase().includes(keyword);
      const matchesCode = !codeFilter || s.semester === codeFilter;
      return matchesKeyword && matchesCode;
    });
  }, [subjects, search, codeFilter]);

  return (
    <Container className="py-4">
      <Navbar bg="dark" data-bs-theme="dark">
        <Container>
          <Nav className="me-auto">
            <h4 style={{ color: "whitesmoke" }}>
              FPT Education Learning Material Portal
            </h4>
          </Nav>
          <Nav className="me-auto">
            <Button onClick={() => navigate(`/login`)} variant="primary">
              Logout
            </Button>
          </Nav>
        </Container>
      </Navbar>
      <h2 className="mb-3">My Courses</h2>

      {error && <Alert variant="danger">{error}</Alert>}

      <Row className="mb-3 g-2 align-items-end">
        <Col>
          <strong>Search by:</strong>
        </Col>
        <Col md={4}>
          <Form.Select
            value={codeFilter}
            onChange={(e) => setCodeFilter(e.target.value)}
          >
            <option value="">Code</option>
            {code.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </Form.Select>
        </Col>
        <Col md={5}>
          <Form.Control
            ref={inputRef}
            placeholder="Enter keyword..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Col>

        <Col>
          {" "}
          <Button
            variant="info"
            onClick={() => {
              inputRef.current.focus();
              setSearch("");
            }}
          >
            Refresh
          </Button>
        </Col>
      </Row>

      {filteredSubjects.length === 0 && (
        <div className="text-center text-muted py-4">
          Không có khóa học nào.
        </div>
      )}

      <Row>
          <Col md={4} className="mb-2">
            <Table bordered hover>
              <thead>
                <tr>
                  <th>Code</th>
                  <th>Name</th>
                  <th>Cuisine</th>
                  <th>MealType</th>
                  <th>Tags</th>
                  <th>Rating</th>
                </tr>
              </thead>
              <tbody>
                {filteredSubjects.map((subject) => (
                  <tr key={subject.id}>
                    <td>{subject.code}</td>
                    <td>
                      <strong>{subject.name}</strong>
                      <br />
                      Preparation Time: {subject.prepTimeMinutes} minutes
                      <br />
                      Cook Time: {subject.cookTimeMinutes} minutes
                    </td>
                    <td>{subject.cuisine}</td>
                    {/* Nối các phần tử mảng lại bằng dấu ";" */}
                    <td>{subject.mealType.join("; ")}</td>
                    <td>{subject.tags.join("; ")}</td>
                    <td>{subject.rating}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </Col>
      </Row>
    </Container>
  );
}

export default SyllabusManager;
